class TestValidateInput:
    """测试 DataHandler.validate_input 方法"""

    # ========== 正常用例 ==========

    def test_validate_input_normal_string(self):
        """测试正常字符串输入"""
        assert DataHandler.validate_input("hello world") == True

    def test_validate_input_with_single_char(self):
        """测试单字符字符串（符合默认min_length=1）"""
        assert DataHandler.validate_input("a") == True

    def test_validate_input_custom_rules_valid(self):
        """测试自定义验证规则且输入完全符合"""
        custom_rules = {
            'min_length': {'value': 5, 'enabled': True},
            'max_length': {'value': 20, 'enabled': True},
            'allow_empty': {'value': False, 'enabled': True},
        }
        assert DataHandler.validate_input("valid_input") == True

    def test_validate_input_mixed_case_string(self):
        """测试混合大小写字符串"""
        assert DataHandler.validate_input("HeLLo123!@#") == True

    def test_validate_input_chinese_characters(self):
        """测试中文字符串"""
        assert DataHandler.validate_input("测试数据") == True

    # ========== 边界用例 ==========

    def test_validate_input_at_min_length_boundary(self):
        """测试刚好等于最小长度边界"""
        custom_rules = {
            'min_length': {'value': 5, 'enabled': True},
            'max_length': {'value': 1000, 'enabled': False},
            'allow_empty': {'value': False, 'enabled': True},
        }
        assert DataHandler.validate_input("12345") == True

    def test_validate_input_at_max_length_boundary(self):
        """测试刚好等于最大长度边界"""
        custom_rules = {
            'min_length': {'value': 1, 'enabled': True},
            'max_length': {'value': 5, 'enabled': True},
            'allow_empty': {'value': False, 'enabled': True},
        }
        assert DataHandler.validate_input("12345") == True

    def test_validate_input_min_length_zero_with_empty(self):
        """测试min_length为0时允许空字符串"""
        custom_rules = {
            'min_length': {'value': 0, 'enabled': True},
            'max_length': {'value': 1000, 'enabled': False},
            'allow_empty': {'value': True, 'enabled': True},
        }
        assert DataHandler.validate_input("") == True

    def test_validate_input_max_length_disabled(self):
        """测试max_length规则禁用时"""
        custom_rules = {
            'min_length': {'value': 1, 'enabled': True},
            'max_length': {'value': 5, 'enabled': False},
            'allow_empty': {'value': False, 'enabled': True},
        }
        assert DataHandler.validate_input("a" * 1000) == True

    def test_validate_input_min_length_disabled(self):
        """测试min_length规则禁用时"""
        custom_rules = {
            'min_length': {'value': 100, 'enabled': False},
            'max_length': {'value': 1000, 'enabled': False},
            'allow_empty': {'value': False, 'enabled': True},
        }
        assert DataHandler.validate_input("x") == True

    # ========== 异常用例 ==========

    def test_validate_input_below_min_length_raises_error(self):
        """测试低于最小长度时抛出ValidationError"""
        custom_rules = {
            'min_length': {'value': 5, 'enabled': True},
            'max_length': {'value': 1000, 'enabled': False},
            'allow_empty': {'value': False, 'enabled': True},
        }
        with pytest.raises(ValidationError) as exc_info:
            DataHandler.validate_input("ab", custom_rules)
        assert "min" in str(exc_info.value.message).lower() or exc_info.value.field is not None

    def test_validate_input_above_max_length_raises_error(self):
        """测试超过最大长度时抛出ValidationError"""
        custom_rules = {
            'min_length': {'value': 1, 'enabled': True},
            'max_length': {'value': 5, 'enabled': True},
            'allow_empty': {'value': False, 'enabled': True},
        }
        with pytest.raises(ValidationError) as exc_info:
            DataHandler.validate_input("abcdef", custom_rules)
        assert "max" in str(exc_info.value.message).lower() or exc_info.value.field is not None

    def test_validate_input_empty_when_not_allowed_raises_error(self):
        """测试不允许空字符串但输入为空"""
        custom_rules = {
            'min_length': {'value': 0, 'enabled': True},
            'max_length': {'value': 1000, 'enabled': False},
            'allow_empty': {'value': False, 'enabled': True},
        }
        with pytest.raises(ValidationError):
            DataHandler.validate_input("", custom_rules)

    def test_validate_input_empty_string_below_min_length(self):
        """测试空字符串低于最小长度要求"""
        custom_rules = {
            'min_length': {'value': 1, 'enabled': True},
            'max_length': {'value': 1000, 'enabled': False},
            'allow_empty': {'value': False, 'enabled': True},
        }
        with pytest.raises(ValidationError):
            DataHandler.validate_input("", custom_rules)

    def test_validate_input_error_has_field_attribute(self):
        """测试ValidationError包含field属性"""
        custom_rules = {
            'min_length': {'value': 5, 'enabled': True},
            'max_length': {'value': 1000, 'enabled': False},
            'allow_empty': {'value': False, 'enabled': True},
        }
        try:
            DataHandler.validate_input("ab", custom_rules)
        except ValidationError as e:
            assert hasattr(e, 'field')

    def test_validate_input_error_has_message_attribute(self):
        """测试ValidationError包含message属性"""
        custom_rules = {
            'min_length': {'value': 5, 'enabled': True},
            'max_length': {'value': 1000, 'enabled': False},
            'allow_empty': {'value': False, 'enabled': True},
        }
        try:
            DataHandler.validate_input("ab", custom_rules)
        except ValidationError as e:
            assert hasattr(e, 'message')
            assert isinstance(e.message, str)

