import sys
import os

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

from src.handler import (
    DataHandler,
    DEFAULT_TRANSFORM_STRATEGY,
    SUPPORTED_STRATEGIES,
    MAX_DATA_SIZE
)


class TestDataHandlerProcess:
    """DataHandler.process() 方法的单元测试"""

    # ===== 正常用例 =====

    def test_process_uppercase_strategy(self):
        """测试 uppercase 策略正常转换"""
        handler = DataHandler(source="test", transform_strategy="uppercase")
        data = {"name": "hello", "city": "beijing"}
        result = handler.process(data)
        assert result == {"name": "HELLO", "city": "BEIJING"}

    def test_process_lowercase_strategy(self):
        """测试 lowercase 策略正常转换"""
        handler = DataHandler(source="test", transform_strategy="lowercase")
        data = {"name": "HELLO", "city": "BEIJING"}
        result = handler.process(data)
        assert result == {"name": "hello", "city": "beijing"}

    def test_process_titlecase_strategy(self):
        """测试 titlecase 策略正常转换"""
        handler = DataHandler(source="test", transform_strategy="titlecase")
        data = {"name": "hello world", "city": "new york"}
        result = handler.process(data)
        assert result == {"name": "Hello World", "city": "New York"}

    def test_process_none_strategy_preserves_original(self):
        """测试 none 策略保留原始值"""
        handler = DataHandler(source="test", transform_strategy="none")
        data = {"name": "Hello", "value": 123}
        result = handler.process(data)
        assert result == {"name": "Hello", "value": 123}

    def test_process_with_default_strategy(self):
        """测试使用默认策略（uppercase）"""
        handler = DataHandler(source="test")
        data = {"key": "value"}
        result = handler.process(data)
        assert result == {"key": "VALUE"}

    def test_process_uses_internal_data_when_input_is_none(self):
        """测试当输入为 None 时使用内部存储的数据"""
        handler = DataHandler(source="test")
        handler.data = {"key": "internal"}
        result = handler.process()
        assert result == {"key": "INTERNAL"}

    def test_process_with_empty_dict(self):
        """测试处理空字典"""
        handler = DataHandler(source="test")
        result = handler.process({})
        assert result == {}

    def test_process_with_mixed_value_types(self):
        """测试处理混合类型值"""
        handler = DataHandler(source="test", transform_strategy="uppercase")
        data = {"str_val": "hello", "int_val": 42, "float_val": 3.14, "bool_val": True, "none_val": None}
        result = handler.process(data)
        assert result == {"str_val": "HELLO", "int_val": 42, "float_val": 3.14, "bool_val": True, "none_val": None}

    def test_process_with_special_characters(self):
        """测试处理包含特殊字符的字符串"""
        handler = DataHandler(source="test", transform_strategy="uppercase")
        data = {"special": "hello @world! #2024"}
        result = handler.process(data)
        assert result == {"special": "HELLO @WORLD! #2024"}

    def test_process_with_unicode_characters(self):
        """测试处理 Unicode 字符"""
        handler = DataHandler(source="test", transform_strategy="lowercase")
        data = {"chinese": "你好", "emoji": "🎉"}
        result = handler.process(data)
        assert result == {"chinese": "你好", "emoji": "🎉"}

    # ===== 边界用例 =====

    def test_process_with_single_key_value(self):
        """测试单键值对处理"""
        handler = DataHandler(source="test")
        result = handler.process({"a": "b"})
        assert result == {"a": "B"}

    def test_process_with_large_dict_at_boundary(self):
        """测试数据大小在边界值（MAX_DATA_SIZE）"""
        handler = DataHandler(source="test")
        data = {f"key_{i}": f"value_{i}" for i in range(MAX_DATA_SIZE)}
        result = handler.process(data)
        assert len(result) == MAX_DATA_SIZE

    def test_process_with_whitespace_only_string(self):
        """测试仅包含空白的字符串"""
        handler = DataHandler(source="test", transform_strategy="uppercase")
        result = handler.process({"space": "   "})
        assert result == {"space": "   "}

    def test_process_with_numeric_string(self):
        """测试纯数字字符串"""
        handler = DataHandler(source="test", transform_strategy="uppercase")
        result = handler.process({"num": "12345"})
        assert result == {"num": "12345"}

    # ===== 异常用例 =====

    def test_process_raises_when_data_exceeds_max_size(self):
        """测试数据超过最大限制时抛出 ValueError"""
        handler = DataHandler(source="test")
        data = {f"key_{i}": f"value_{i}" for i in range(MAX_DATA_SIZE + 1)}
        with pytest.raises(ValueError, match=f"Data size exceeds maximum limit of {MAX_DATA_SIZE}"):
            handler.process(data)

    def test_init_raises_with_unsupported_strategy(self):
        """测试不支持的策略抛出 ValueError"""
        with pytest.raises(ValueError, match="Unsupported strategy"):
            DataHandler(source="test", transform_strategy="invalid_strategy")

    def test_init_raises_with_empty_strategy(self):
        """测试空字符串策略抛出 ValueError"""
        with pytest.raises(ValueError, match="Unsupported strategy"):
            DataHandler(source="test", transform_strategy="")

    def test_process_with_none_input_and_empty_internal_data(self):
        """测试无输入数据且内部数据为空"""
        handler = DataHandler(source="test")
        result = handler.process()
        assert result == {}

    def test_process_with_incorrect_value_type_in_strategy(self):
        """测试策略对错误类型值的处理（应保持原样）"""
        handler = DataHandler(source="test", transform_strategy="uppercase")
        result = handler.process({"key": ["list", "items"]})
        assert result == {"key": ["list", "items"]}

    def test_process_with_dict_value(self):
        """测试值为字典时的处理"""
        handler = DataHandler(source="test", transform_strategy="uppercase")
        result = handler.process({"key": {"nested": "value"}})
        assert result == {"key": {"nested": "value"}}

    def test_process_with_list_value(self):
        """测试值为列表时的处理"""
        handler = DataHandler(source="test", transform_strategy="uppercase")
        result = handler.process({"key": [1, 2, 3]})
        assert result == {"key": [1, 2, 3]}

    def test_process_with_zero_length_string(self):
        """测试空字符串处理"""
        handler = DataHandler(source="test", transform_strategy="uppercase")
        result = handler.process({"empty": ""})
        assert result == {"empty": ""}

    def test_process_multiple_times_with_same_handler(self):
        """测试同一处理器多次调用 process"""
        handler = DataHandler(source="test", transform_strategy="uppercase")
        data1 = {"a": "first"}
        data2 = {"b": "second"}
        result1 = handler.process(data1)
        result2 = handler.process(data2)
        assert result1 == {"a": "FIRST"}
        assert result2 == {"b": "SECOND"}

